// getGCSObjectBytes calls the GCS storage client with objAttrs information, and returns the object's raw bytes.
func (h *EventHandler[T, P]) getGCSObjectBytes(ctx context.Context, objAttrs map[string]string) ([]byte, error) {
	// Get bucket and object id from message attributes.
	bucketID, found := objAttrs["bucketId"]
	if !found {
		return nil, fmt.Errorf("bucket ID not found")
	}
	objectID, found := objAttrs["objectId"]
	if !found {
		return nil, fmt.Errorf("object ID not found")
	}

	// Read the object from bucket.
	rc, err := h.client.Bucket(bucketID).Object(objectID).NewReader(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to create GCS object reader: %w", err)
	}
	defer rc.Close()
	yb, err := io.ReadAll(io.LimitReader(rc, gcsObjectSizeLimitInBytes))
	if err != nil {
		return nil, fmt.Errorf("failed to read object from GCS: %w", err)
	}
	return yb, nil
}

// unmarshalObjectProto converts the object yaml bytes into a proto message wrapper.
func unmarshalObjectProto[T any, P ProtoWrapper[T]](yb []byte) (P, error) {
	p := P(new(T))
	if err := protoutil.FromYAML(yb, p); err != nil {
		return nil, pmaperrors.New(fmt.Sprintf("failed to unmarshal object yaml: %v", err))
	}
	return p, nil
}

